/// <summary>
/// UI Builder class : to update Vendor address
/// </summary>
class MET_VendorAddsUpdateUIBuilder extends SrsReportDataContractUIBuilder
{
    MET_VendorAddsUpdateContract    contract;
    DialogField		                availableCompanies;
    
 
}

Method.Source:
   public void postBuild()
   {
       contract		= this.dataContractObject() as MET_VendorAddsUpdateContract;
       availableCompanies	= this.bindInfo().getDialogField(contract, methodStr(MET_VendorAddsUpdateContract, parmSelectedLegalEntities));

       availableCompanies.lookupButton(FormLookupButton::Always);
   }

   public void postRun()
   {
       Query		        query		    = new Query();
       QueryBuildDataSource    qbdsLegalEntity     = query.addDataSource(tablenum(ERDataAreaView));

       qbdsLegalEntity.fields().addField(fieldNum(ERDataAreaView, id));
       qbdsLegalEntity.fields().addField(fieldNum(ERDataAreaView, Name));

       container selectedFields = [tableNum(ERDataAreaView), fieldNum(ERDataAreaView, Id)];

       SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), availableCompanies.control(), query, false, selectedFields);
   }
